const response = $input.first().json;
const entries = response.entries || [];

if (entries.length === 0) {
  return [{
    json: {
      message: "🌅 *Second Brain | Briefing Diario*\n\n¡Todo limpio! No tienes tareas pendientes registradas para hoy."
    }
  }];
}

const AREA_ICONS = {
  trabajo: "💼",
  universidad: "🎓",
  gimnasio: "🏋️",
  cashea: "💳",
  personal: "🧠"
};

const grouped = {};
entries.forEach(entry => {
  const area = entry.area || 'personal';
  if (!grouped[area]) grouped[area] = [];
  grouped[area].push(entry);
});

let message = `🌅 *Second Brain | Briefing Diario*\n📅 *Total de pendientes:* ${entries.length}\n\n`;

for (const [area, tasks] of Object.entries(grouped)) {
  const icon = AREA_ICONS[area] || '📌';
  const areaName = area.toUpperCase();
  message += `${icon} *${areaName}* (${tasks.length})\n`;

  tasks.forEach(t => {
    message += `  • ${t.title}\n`;
    if (t.content && Array.isArray(t.content) && t.content.length > 0) {
      t.content.forEach(b => {
        if (b.type === 'todo') {
          const done = b.metadata?.is_completed ? '✅' : '⏳';
          message += `    ${done} ${b.content}\n`;
        }
      });
    }
  });
  message += `\n`;
}

message += `⚡ _¡A por un día productivo!_`;

return [{
  json: {
    message,
    total: entries.length
  }
}];
